import type { Transition } from "motion/react";

export const easeOut = [0.23, 1, 0.32, 1] as const;

export const easeInOut = [0.77, 0, 0.175, 1] as const;

export const easeOutClass = "ease-[cubic-bezier(0.23,1,0.32,1)]";

export const duration = {
  fast: 0.14,
  base: 0.2,
  slow: 0.28,
} as const;

export const springSnappy = {
  type: "spring",
  duration: 0.24,
  bounce: 0,
} as const satisfies Transition;

export const springLayout = {
  type: "spring",
  duration: 0.3,
  bounce: 0,
} as const satisfies Transition;

export function transitionFor(
  reduceMotion: boolean | null,
  transition: Transition,
): Transition {
  return reduceMotion ? { duration: 0 } : transition;
}

export function edgeOffset(placement: string | null, distance: number) {
  switch (placement) {
    case "top":
      return { x: 0, y: distance };
    case "left":
      return { x: distance, y: 0 };
    case "right":
      return { x: -distance, y: 0 };
    default:
      return { x: 0, y: -distance };
  }
}

import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import {
  AnimatePresence,
  animate,
  motion,
  useMotionValue,
  useMotionValueEvent,
  useReducedMotion,
} from "motion/react";
import { type ComponentProps, useEffect, useMemo, useState } from "react";
import { easeOut } from "./motion";
import { cn } from "./utils";

export interface AnimatedNumberProps
  extends Omit<ComponentProps<"span">, "children"> {
  value: number;
  locale?: string;
  formatOptions?: Intl.NumberFormatOptions;
  variant?: "count" | "slide";
}

export function AnimatedNumber({
  value,
  locale = "en-US",
  formatOptions,
  variant = "count",
  className,
  ...props
}: AnimatedNumberProps) {
  const reducedMotion = useReducedMotion();
  const formatter = useMemo(
    () =>
      new Intl.NumberFormat(
        locale,
        formatOptions ?? { maximumFractionDigits: 0 },
      ),
    [locale, formatOptions],
  );

  return (
    <span
      {...props}
      data-slot="animated-number"
      data-variant={variant}
      className={cn("tabular-nums", className)}
    >
      {variant === "slide" ? (
        <SlidingNumber
          value={value}
          formatter={formatter}
          reducedMotion={reducedMotion}
        />
      ) : (
        <CountingNumber
          value={value}
          formatter={formatter}
          reducedMotion={reducedMotion}
        />
      )}
      <span className="sr-only">{formatter.format(value)}</span>
    </span>
  );
}

interface NumberDisplayProps {
  value: number;
  formatter: Intl.NumberFormat;
  reducedMotion: boolean | null;
}

function CountingNumber({
  value,
  formatter,
  reducedMotion,
}: NumberDisplayProps) {
  const number = useMotionValue(value);
  const [displayed, setDisplayed] = useState(value);

  useMotionValueEvent(number, "change", setDisplayed);

  useEffect(() => {
    if (reducedMotion) {
      number.set(value);
      return;
    }
    const controls = animate(number, value, {
      duration: 0.45,
      ease: easeOut,
    });
    return () => controls.stop();
  }, [number, reducedMotion, value]);

  return (
    <span aria-hidden="true">
      {formatter.format(reducedMotion ? value : displayed)}
    </span>
  );
}

const slideVariants = {
  enter: (direction: number) => ({
    y: direction > 0 ? "100%" : "-100%",
    opacity: 0,
  }),
  center: { y: "0%", opacity: 1 },
  exit: (direction: number) => ({
    y: direction > 0 ? "-100%" : "100%",
    opacity: 0,
  }),
};

function SlidingDigit({
  digit,
  direction,
}: {
  digit: string;
  direction: number;
}) {
  return (
    <span
      data-slot="animated-number-digit"
      className="-mx-[0.06em] inline-grid overflow-hidden px-[0.06em] align-baseline"
    >
      <AnimatePresence initial={false} custom={direction}>
        <motion.span
          key={digit}
          custom={direction}
          variants={slideVariants}
          initial="enter"
          animate="center"
          exit="exit"
          transition={{ duration: 0.24, ease: easeOut }}
          className="col-start-1 row-start-1"
        >
          {digit}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

function SlidingNumber({
  value,
  formatter,
  reducedMotion,
}: NumberDisplayProps) {
  const [change, setChange] = useState({
    value,
    direction: 1,
  });
  if (value !== change.value) {
    setChange({
      value,
      direction: value > change.value ? 1 : -1,
    });
  }

  if (reducedMotion) {
    return <span aria-hidden="true">{formatter.format(value)}</span>;
  }

  const parts = formatter.formatToParts(value);
  let integerPlace = parts
    .filter((part) => part.type === "integer")
    .reduce((count, part) => count + Array.from(part.value).length, 0);
  let fractionPlace = 0;
  const otherCounts = new Map<string, number>();

  const segments = parts.flatMap((part) => {
    if (part.type === "integer") {
      return Array.from(part.value, (digit) => ({
        key: `integer-${--integerPlace}`,
        text: digit,
        isDigit: true,
      }));
    }
    if (part.type === "fraction") {
      return Array.from(part.value, (digit) => ({
        key: `fraction-${fractionPlace++}`,
        text: digit,
        isDigit: true,
      }));
    }
    if (part.type === "group") {
      return [
        { key: `group-${integerPlace}`, text: part.value, isDigit: false },
      ];
    }
    const occurrence = otherCounts.get(part.type) ?? 0;
    otherCounts.set(part.type, occurrence + 1);
    return [
      {
        key: `${part.type}-${occurrence}`,
        text: part.value,
        isDigit: false,
      },
    ];
  });

  return (
    <span
      aria-hidden="true"
      className="inline-flex whitespace-nowrap align-baseline"
    >
      {segments.map(({ key, text, isDigit }) =>
        isDigit ? (
          <SlidingDigit key={key} digit={text} direction={change.direction} />
        ) : (
          <span key={key}>{text}</span>
        ),
      )}
    </span>
  );
}

import type { HTMLAttributes } from "react";
import { tv, type VariantProps } from "tailwind-variants";
import { cn } from "./utils";

const badgeStyles = tv({
  base: "inline-flex min-h-7 items-center gap-1.5 rounded-full px-3 py-1 text-xs font-medium leading-4 tracking-normal shadow-[var(--shadow-card)] ring-1",
  variants: {
    variant: {
      neutral: "bg-secondary text-secondary-foreground ring-border",
      accent: "bg-accent text-accent-foreground ring-primary/15",
      success: "bg-success-subtle text-success-foreground ring-success/15",
      warning: "bg-warning-subtle text-warning-foreground ring-warning/20",
      error: "bg-card text-destructive ring-destructive/25",
      outline: "bg-transparent text-foreground ring-border",
    },
  },
  defaultVariants: { variant: "neutral" },
});

export interface BadgeProps extends HTMLAttributes<HTMLSpanElement> {
  variant?: NonNullable<VariantProps<typeof badgeStyles>["variant"]>;
  dot?: boolean;
}

export function Badge({
  variant = "neutral",
  dot = false,
  className,
  children,
  ...props
}: BadgeProps) {
  return (
    <span
      data-slot="badge"
      data-variant={variant}
      className={badgeStyles({ variant, className })}
      {...props}
    >
      {dot && <BadgeDot />}
      {children}
    </span>
  );
}

export function BadgeDot({
  className,
  ...props
}: HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      aria-hidden="true"
      {...props}
      data-slot="badge-dot"
      className={cn("size-1.5 rounded-full bg-current", className)}
    />
  );
}

import type { ComponentProps } from "react";
