}

export function StatDetail({ className, ...props }: ComponentProps<"p">) {
  return (
    <p
      data-slot="stat-detail"
      className={cn("mt-2 text-xs leading-5 text-muted-foreground", className)}
      {...props}
    />
  );
}

"use client";

import { LayoutGroup } from "motion/react";
import { createContext, useId } from "react";
import {
  ToggleButtonGroup as AriaToggleButtonGroup,
  composeRenderProps,
  type ToggleButtonGroupProps,
} from "react-aria-components";
import { cn } from "./utils";

export const SingleToggleGroupContext = createContext(false);

export function ToggleButtonGroup({
  className,
  ...props
}: ToggleButtonGroupProps) {
  const groupId = useId();
  return (
    <LayoutGroup id={groupId}>
      <SingleToggleGroupContext.Provider
        value={props.selectionMode !== "multiple"}
      >
        <AriaToggleButtonGroup
          {...props}
          data-slot="toggle-button-group"
          className={composeRenderProps(className, (className) =>
            cn(
              "inline-flex w-fit max-w-full flex-wrap gap-1 rounded-lg border border-border bg-secondary p-1 data-[orientation=vertical]:flex-col",
              className,
            ),
          )}
        />
      </SingleToggleGroupContext.Provider>
    </LayoutGroup>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { useContext } from "react";
import {
  ToggleButton as AriaToggleButton,
  composeRenderProps,
  type ToggleButtonProps,
} from "react-aria-components";
import { tv, type VariantProps } from "tailwind-variants";
import { springLayout, transitionFor } from "./motion";
import { cn } from "./utils";
import { SingleToggleGroupContext } from "./toggle-button-group";

const toggleButtonStyles = tv({
  base: "inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-md px-4 text-sm font-medium transition-[color,background-color,border-color,box-shadow,scale] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] motion-safe:pressed:scale-[0.96] disabled:cursor-default disabled:opacity-50 focus-visible:z-10 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring [&_svg]:pointer-events-none [&_svg]:shrink-0",
  variants: {
    variant: {
      default:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted pressed:bg-muted selected:border-primary/40 selected:bg-accent selected:text-accent-foreground",
      segmented:
        "border border-transparent bg-transparent px-3 text-muted-foreground shadow-none hover:bg-card/70 hover:text-foreground pressed:bg-card/70 selected:border-border selected:bg-card selected:text-foreground selected:shadow-[var(--shadow-card)] sm:min-h-9",
      ghost:
        "border border-transparent bg-transparent text-foreground hover:bg-muted pressed:bg-muted selected:bg-accent selected:text-accent-foreground",
    },
  },
  defaultVariants: { variant: "default" },
});

export interface ToggleButtonStyleProps extends ToggleButtonProps {
  variant?: NonNullable<VariantProps<typeof toggleButtonStyles>["variant"]>;
}

export function ToggleButton({
  className,
  children,
  variant = "default",
  ...props
}: ToggleButtonStyleProps) {
  const reduceMotion = useReducedMotion();
  const groupedSelection =
    useContext(SingleToggleGroupContext) && variant === "segmented";
  return (
    <AriaToggleButton
      {...props}
      data-slot="toggle-button"
      data-variant={variant}
      className={composeRenderProps(className, (className) =>
        toggleButtonStyles({
          variant,
          className: cn(
            groupedSelection &&
              "relative isolate selected:border-transparent selected:bg-transparent selected:shadow-none",
            className,
          ),
        }),
      )}
    >
      {composeRenderProps(children, (content, { isSelected }) => (
        <>
          {groupedSelection && isSelected && (
            <motion.span
              layoutId="toggle-group-selection"
              initial={false}
              aria-hidden="true"
              transition={transitionFor(reduceMotion, springLayout)}
              className="pointer-events-none absolute inset-0 -z-10 rounded-md border border-border bg-card shadow-[var(--shadow-card)] forced-colors:border-[Highlight]"
            />
          )}
          {content}
        </>
      ))}
    </AriaToggleButton>
  );
}

"use client";

import { TrendDownIcon, TrendUpIcon } from "@phosphor-icons/react";
import { useState } from "react";
import { AnimatedNumber } from "../../../components/vip-ui/animated-number";
import { Badge } from "../../../components/vip-ui/badge";
import { Stat, StatDetail, StatLabel } from "../../../components/vip-ui/stat";
import { ToggleButton } from "../../../components/vip-ui/toggle-button";
import { ToggleButtonGroup } from "../../../components/vip-ui/toggle-button-group";

type Period = "7d" | "30d" | "90d";

const periodLabels: Record<Period, string> = {
  "7d": "7 days",
  "30d": "30 days",
  "90d": "90 days",
};

interface Metric {
  label: string;
  format: Intl.NumberFormatOptions;
  direction: 1 | -1;
  values: Record<Period, { value: number; change: number; trend: number[] }>;
}

const metrics: Metric[] = [
  {
    label: "Monthly recurring revenue",
    format: { style: "currency", currency: "USD", maximumFractionDigits: 0 },
    direction: 1,
    values: {
      "7d": { value: 18420, change: 2.1, trend: [8, 9, 9, 10, 11, 10, 12] },
      "30d": { value: 74310, change: 8.6, trend: [5, 6, 6, 8, 7, 9, 10, 12] },
      "90d": { value: 201880, change: 21.4, trend: [3, 4, 6, 6, 8, 9, 11, 13] },
    },
  },
  {
    label: "Active users",
    format: { maximumFractionDigits: 0 },
    direction: 1,
    values: {
      "7d": { value: 3912, change: 1.4, trend: [6, 7, 6, 7, 8, 8, 8] },
      "30d": { value: 8204, change: 5.2, trend: [5, 6, 7, 6, 7, 8, 9, 9] },
      "90d": { value: 12650, change: 14.9, trend: [3, 4, 5, 7, 7, 8, 10, 11] },
    },
  },
  {
    label: "Churn rate",
    format: { style: "percent", maximumFractionDigits: 1 },
    direction: -1,
    values: {
      "7d": { value: 0.021, change: -0.2, trend: [9, 8, 8, 7, 7, 6, 6] },
      "30d": { value: 0.024, change: -0.6, trend: [10, 9, 9, 8, 8, 7, 7, 6] },
      "90d": { value: 0.027, change: 0.3, trend: [6, 7, 7, 8, 7, 8, 8, 9] },
    },
  },
  {
    label: "Average response time",
    format: { style: "unit", unit: "millisecond", maximumFractionDigits: 0 },
    direction: -1,
    values: {
      "7d": { value: 182, change: -4.8, trend: [9, 8, 9, 7, 7, 6, 5] },
      "30d": { value: 196, change: -2.2, trend: [8, 8, 7, 8, 7, 7, 6, 6] },
      "90d": { value: 214, change: 3.5, trend: [5, 6, 6, 7, 6, 7, 8, 8] },
    },
  },
];

function Sparkline({ points, good }: { points: number[]; good: boolean }) {
  const max = Math.max(...points);
  const min = Math.min(...points);
  const range = max - min || 1;
  const path = points
    .map((point, index) => {
      const x = (index / (points.length - 1)) * 100;
      const y = 28 - ((point - min) / range) * 24;
      return `${index === 0 ? "M" : "L"}${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(" ");

  return (
    <svg
      viewBox="0 0 100 32"
      preserveAspectRatio="none"
      aria-hidden="true"
      className={`size-full ${good ? "text-success" : "text-destructive"}`}
    >
      <path
        d={`${path} L100,32 L0,32 Z`}
        fill="currentColor"
        fillOpacity={0.12}
      />
      <path
        d={path}
        fill="none"
        stroke="currentColor"
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
        vectorEffect="non-scaling-stroke"
      />
    </svg>
  );
}

export function StatsCards() {
  const [period, setPeriod] = useState<Period>("30d");

  return (
    <section aria-labelledby="stats-title" className="grid gap-5">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1
            id="stats-title"
            className="text-xl font-semibold tracking-[-0.035em]"
          >
            Business health
          </h1>
          <p className="mt-1 text-sm text-muted-foreground">
            Compared with the previous {periodLabels[period]}
          </p>
        </div>
        <ToggleButtonGroup
          aria-label="Period"
          selectionMode="single"
          disallowEmptySelection
          selectedKeys={[period]}
          onSelectionChange={(keys) => {
            const [next] = keys;
            if (next) setPeriod(next as Period);
          }}
        >
          {(Object.keys(periodLabels) as Period[]).map((key) => (
            <ToggleButton key={key} id={key} variant="segmented">
              {periodLabels[key]}
            </ToggleButton>
          ))}
        </ToggleButtonGroup>
      </div>
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {metrics.map((metric) => {
          const current = metric.values[period];
          const good = current.change * metric.direction > 0;
          const TrendIcon = current.change > 0 ? TrendUpIcon : TrendDownIcon;
          return (
            <Stat key={metric.label} className="grid gap-0 overflow-hidden p-0">
              <div className="px-5 pt-5">
                <StatLabel>{metric.label}</StatLabel>
                <p className="mt-2 flex flex-wrap items-baseline gap-x-2 gap-y-1">
                  <AnimatedNumber
                    value={current.value}
                    formatOptions={metric.format}
                    className="text-3xl font-semibold tracking-[-0.045em]"
                  />
                  <Badge
                    variant={good ? "success" : "error"}
                    className="min-h-6 gap-1 px-2 py-0.5"
                  >
                    <TrendIcon size={13} weight="bold" aria-hidden="true" />
                    {current.change > 0 ? "+" : "−"}
                    {Math.abs(current.change)}%
                  </Badge>
                </p>
                <StatDetail>
                  {good ? "Better" : "Worse"} than the previous{" "}
                  {periodLabels[period]}
                </StatDetail>
              </div>
              <div className="mt-3 h-14">
                <Sparkline points={current.trend} good={good} />
              </div>
            </Stat>
          );
        })}
      </div>
    </section>
  );
}
